//! Wolfram golden replay: SI unit conversion factors.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `fixtures/units_golden.wls` under Wolfram Engine 15.0.0) derives every
//! `to_si_factor` in the parser table from `Quantity`/`UnitConvert`,
//! including the exact inch, the degree, and two compound expressions.
//! A wrong factor silently rescales every downstream mesh and material
//! quantity, so the replay checks each symbol plus compound
//! multiply/divide paths.

use meshlang_ast::units::Unit;
use std::collections::HashMap;

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, serde::Deserialize)]
struct Entry {
    value: String,
    exact: String,
}

#[derive(Debug, serde::Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, serde::Deserialize)]
struct Fixture {
    meta: Meta,
    values: HashMap<String, Entry>,
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram units fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

fn golden(fixture: &Fixture, name: &str) -> f64 {
    fixture.values[name]
        .value
        .parse()
        .expect("golden is a decimal")
}

#[test]
fn si_factors_match_wolfram() {
    let fixture = parse_fixture();
    assert!(
        fixture.values["deg"].exact.contains("Degrees"),
        "degree golden must document its Wolfram unit"
    );
    for symbol in [
        "mm", "cm", "km", "in", "um", "ms", "us", "g", "deg", "kHz", "MHz", "kPa", "MPa", "pct",
    ] {
        // The fixture keys use the parser's own spellings; `%` is `pct`.
        let source = if symbol == "pct" { "%" } else { symbol };
        let unit = Unit::parse(source).expect("fixture symbol parses");
        let expected = golden(&fixture, symbol);
        let rel = ((unit.to_si_factor - expected) / expected).abs();
        assert!(
            rel < 1e-15,
            "{source}: Rust {} vs Wolfram {expected}",
            unit.to_si_factor
        );
    }
}

#[test]
fn compound_unit_arithmetic_matches_wolfram() {
    // Compound expressions go through the full expression grammar
    // (`factor ((* | /) factor)*`), pinning factor combination end to end.
    let fixture = parse_fixture();
    for (source, name) in [("km/ms", "km_per_ms"), ("MPa/mm", "MPa_per_mm")] {
        let unit = Unit::parse(source).expect("compound unit parses");
        let expected = golden(&fixture, name);
        let rel = ((unit.to_si_factor - expected) / expected).abs();
        assert!(
            rel < 1e-15,
            "{source}: Rust {} vs Wolfram {expected}",
            unit.to_si_factor
        );
    }
}
